var ElEdo=$("#state");var ElPai=$("#country");function ajaxCall(data,url,success,type){type=type||"json";var successRes=function(data){success(data);};var errorRes=function(e){console.log("Error found \nError Code: "+e.status+" \nError Message: "+e.statusText);};$.ajax({url:url,type:"post",data:data,headers:{"X-CSRF-TOKEN":token,csrftoken:token,},success:successRes,error:errorRes,dataType:type,timeout:60000});}function CambioEstado(){$("#state option:gt(0)").remove();var country=$(ElPai).val();var data={country:country};$(ElEdo).find("option:eq(0)").html("Por favor espera...");ajaxCall(data,UrlEstado,function(data){$(ElEdo).html("").find("option:eq(0)").html(data.text);var _select=$("<select>");var datos=data.data;$.each(datos,function(key,val){_select.append($("<option>").val(val.id).html(val.name));});$(ElEdo).append(_select.html());if($(ElPai).val()!=null||$(ElPai).val()!=0){$(ElEdo).val(edo).trigger("change");}});}$(ElPai).on("change",function(){CambioEstado();EnableElement(ElEdo,false);});$(window).on("load",function(){if($(ElPai).val()!=null||$(ElPai).val()!=0){$(ElPai).val(pai).trigger("change");}});(function($){$.fn.serializeFormJSON=function(){var o={};var a=this.serializeArray();$.each(a,function(){if(o[this.name]){if(!o[this.name].push){o[this.name]=[o[this.name]];}o[this.name].push(this.value||"");}else{o[this.name]=this.value||"";}});return o;};})(jQuery);